begin;select plan(19);
select ok(to_regclass('public.match_results') is not null,'results exist');select ok(to_regclass('public.result_revisions') is not null,'immutable revisions exist');select ok(to_regclass('public.result_confirmations') is not null,'confirmations exist');select ok(to_regclass('public.official_results') is not null,'official results exist');select ok(to_regclass('private.rating_ledger') is not null,'rating ledger exists');
select has_function('public','submit_match_result',array['uuid','jsonb','uuid']);select has_function('public','confirm_match_result',array['uuid','uuid','uuid']);select has_function('private','finalize_match_result',array['uuid']);
select ok(exists(select 1 from pg_proc where oid=to_regprocedure('private.accept_club_result(uuid,uuid,boolean)') and lower(prosrc) like '%for update%'),'finalization locks state');select ok(exists(select 1 from pg_proc where oid=to_regprocedure('private.accept_club_result(uuid,uuid,boolean)') and prosrc like '%player_ranked_eligible%'),'ranked eligibility rechecked');select ok(exists(select 1 from pg_indexes where indexname='official_results_one_match_idx'),'one official result per match');select ok(exists(select 1 from pg_constraint where conname='result_confirmations_pkey'),'one confirmation per player/revision');
select ok(not has_table_privilege('authenticated','public.official_results','INSERT'),'official results cannot be directly inserted');select ok(not has_table_privilege('authenticated','public.result_revisions','UPDATE'),'revisions cannot be rewritten');select ok(not has_table_privilege('authenticated','private.rating_ledger','DELETE'),'rating ledger is append-only');select ok(coalesce((select relrowsecurity from pg_class where oid=to_regclass('public.match_results')),false),'result RLS enabled');select ok(exists(select 1 from pg_indexes where indexname='result_revision_request_idx'),'submission idempotency indexed');
select ok(exists(select 1 from pg_trigger where tgname='official_result_trust' and not tgisinternal),'finalization records confirmation Trust Score effects');select ok(exists(select 1 from pg_trigger where tgname='official_result_calculation_broadcast' and not tgisinternal),'calculation changes broadcast an invalidation');
select * from finish();rollback;
